// Caveman native extension for Pi. One model-visible tool (caveman_retrieve),
// lifecycle bridged into the Caveman native runtime, gated provider routing to
// the local proxy, byte-stable Core injection, and post-tool output shrinking.
//
// Factory rule: register everything synchronously, start nothing. Pi runs
// factories for non-session invocations (model listing), so every background
// resource (proxy check, MCP child) waits for session_start.

import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { Type } from "typebox";
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { HookBridge, promptDigest, taskContinuation, taskTerms, taskType } from "./lifecycle.ts";
import { MAX_CONTEXT_BYTES, additionalContextOf } from "./protocol.ts";
import { ProviderRouter } from "./provider.ts";
import { RecoveryClient } from "./recovery.ts";
import { shrinkToolResult } from "./tool-output.ts";

const HEALTH_TIMEOUT_MS = 750;
const RECOVERY_TOOL = "caveman_retrieve";

function cavemanHome(): string {
  return process.env.CAVEMAN_HOME || join(homedir(), ".caveman");
}

function gatewayUrl(): string {
  const env = process.env.CAVE_GATEWAY_URL?.trim();
  if (env) return env;
  try {
    const config = JSON.parse(readFileSync(join(homedir(), ".caveman-cloud", "config.json"), "utf8"));
    if (typeof config.gatewayUrl === "string" && config.gatewayUrl) return config.gatewayUrl;
  } catch { /* no config — default below */ }
  return "http://127.0.0.1:8787";
}

function runStateRecoveryViaMcp(gateway: string): boolean | undefined {
  let port: string;
  try {
    const url = new URL(gateway);
    port = url.port || (url.protocol === "https:" ? "443" : "80");
  } catch {
    return undefined;
  }
  try {
    const state = JSON.parse(readFileSync(join(cavemanHome(), "run", `${port}.json`), "utf8"));
    // A SIGKILL'd proxy leaves its run-state file behind by design; mirror the
    // CLI's field validation and require the recorded pid to still be alive so
    // a stale file (or a stranger on the port) can never open the gate.
    if (state?.schema !== "caveman.proxy.run.v1") return undefined;
    if (typeof state.pid !== "number" || typeof state.instance_token !== "string") return undefined;
    if (state.owner !== "wrap" && state.owner !== "start") return undefined;
    try {
      process.kill(state.pid, 0);
    } catch {
      return undefined;
    }
    return Boolean(state.recovery_via_mcp);
  } catch {
    return undefined;
  }
}

async function proxyAliveOnce(gateway: string): Promise<boolean> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), HEALTH_TIMEOUT_MS);
  try {
    const response = await fetch(`${gateway.replace(/\/+$/, "")}/health/live`, { signal: controller.signal });
    await response.body?.cancel();
    return response.ok;
  } catch {
    return false;
  } finally {
    clearTimeout(timer);
  }
}

// A proxy the SessionStart hook just autostarted may be a few hundred ms behind
// the first probe; retry briefly before declaring the session direct.
async function proxyAlive(gateway: string): Promise<boolean> {
  for (let attempt = 0; attempt < 3; attempt++) {
    if (await proxyAliveOnce(gateway)) return true;
    await new Promise((resolve) => setTimeout(resolve, 300));
  }
  return false;
}

export default function (pi: ExtensionAPI) {
  const bridge = new HookBridge();
  const recovery = new RecoveryClient();
  let router: ProviderRouter | undefined;
  let sessionId = "default";
  let coreContext: string | undefined;
  let pendingContext: string[] = [];
  let pendingBytes = 0;
  let gateDone = false;

  const notify = (ctx: ExtensionContext | undefined, message: string, kind: "warning" | "info") => {
    if (ctx?.hasUI) ctx.ui.notify(message, kind);
    else process.stderr.write(`${message}\n`);
  };

  // Diagnostics only; CAVEMAN_PI_DEBUG=1 traces handler entry/exit to stderr.
  const debug = (message: string) => {
    if (process.env.CAVEMAN_PI_DEBUG === "1") process.stderr.write(`[caveman-pi] ${message}\n`);
  };

  // An extension exception must never crash Pi.
  const guardedBase = <H extends (...args: never[]) => unknown>(fn: H, label = fn.name || "handler"): H =>
    (async (...args: Parameters<H>) => {
      try {
        debug(`enter ${label}`);
        const result = await fn(...args);
        debug(`exit ${label}`);
        return result;
      } catch (error) {
        process.stderr.write(`caveman pi extension: ${(error as Error).message}\n`);
        return undefined;
      }
    }) as unknown as H;

  const GUARD = (label: string) => <H extends (...args: never[]) => unknown>(fn: H): H => guardedBase(fn, label);
  const GUARD_session_start = GUARD("session_start");
  const GUARD_model_select = GUARD("model_select");
  const GUARD_before_agent_start = GUARD("before_agent_start");
  const GUARD_turn_start = GUARD("turn_start");
  const GUARD_turn_end = GUARD("turn_end");
  const GUARD_tool_call = GUARD("tool_call");
  const GUARD_tool_result = GUARD("tool_result");
  const GUARD_session_before_compact = GUARD("session_before_compact");
  const GUARD_session_compact = GUARD("session_compact");
  const GUARD_session_shutdown = GUARD("session_shutdown");

  pi.registerTool({
    name: RECOVERY_TOOL,
    label: "Retrieve compressed context",
    description: "Recover exact original content from a Caveman recovery handle.",
    parameters: Type.Object({
      recovery_handle: Type.String({ description: "Exact ccr_ handle returned by Caveman or copied from a <<ccr:HANDLE>> marker." }),
      query: Type.Optional(Type.String({ description: "One broad description covering every detail needed from this handle." })),
    }),
    async execute(_toolCallId, params, signal) {
      const result = await recovery.retrieve(params.recovery_handle, params.query, signal);
      // MCP errors surface as Pi tool errors (thrown), never as fabricated content.
      if (result.isError) throw new Error(result.text || "caveman_retrieve failed");
      return { content: [{ type: "text", text: result.text }], details: { recovery_handle: params.recovery_handle } };
    },
  });

  pi.on("session_start", GUARD_session_start(async (_event: unknown, ctx: ExtensionContext) => {
    router ??= new ProviderRouter(pi, (message, kind) => notify(ctx, message, kind));
    // A new/resumed/forked session replaces the runtime; reset everything.
    gateDone = false;
    coreContext = undefined;
    pendingContext = [];
    pendingBytes = 0;
    try {
      sessionId = ctx.sessionManager.getSessionId() || "default";
    } catch {
      sessionId = "default";
    }
    const start = await bridge.call("SessionStart", { session_id: sessionId });
    coreContext = additionalContextOf(start);
    if (!start) {
      // No native runtime reachable means no Core and no lifecycle decisions;
      // routing without them would be compression theater.
      gateDone = true;
      notify(ctx, "Caveman: direct mode, no compression this session (caveman native runtime unreachable)", "warning");
      return;
    }

    // Recovery gate: route only when the proxy is alive AND it published MCP
    // recovery AND this session's recovery client actually initialized. Both
    // must be TRUE — this extension always registers caveman_retrieve, which
    // disables the proxy's server-side retrieve fallback, so a "both false"
    // session could never compress anything and must stay direct instead.
    const gateway = gatewayUrl();
    const alive = await proxyAlive(gateway);
    const published = runStateRecoveryViaMcp(gateway);
    const recoveryReady = alive ? await recovery.ensure() : false;
    gateDone = true;
    if (!alive || published === undefined) {
      notify(ctx, "Caveman: direct mode, no compression this session (local proxy not running)", "warning");
      return;
    }
    if (!published || !recoveryReady) {
      notify(ctx, "Caveman: direct mode, no compression this session (recovery not available — run `caveman doctor pi`)", "warning");
      return;
    }
    await router.openGate(gateway, ctx);
  }));

  pi.on("model_select", GUARD_model_select(async (event: { model: ExtensionContext["model"] }, ctx: ExtensionContext) => {
    // Covers /model, Ctrl+P cycling, and resume/fork restores. Before the gate
    // has run (restore fires early), routing is deferred to session_start.
    if (gateDone) await router?.apply(event.model, ctx);
  }));

  pi.on("before_agent_start", GUARD_before_agent_start(async (event: { prompt: string; systemPrompt: string }, ctx: ExtensionContext) => {
    const response = await bridge.call("UserPromptSubmit", {
      session_id: sessionId,
      model: ctx.model?.id,
      provider: ctx.model?.provider,
      prompt: promptDigest(event.prompt),
      task_type: taskType(event.prompt),
      task_terms: taskTerms(event.prompt),
      task_continuation: taskContinuation(event.prompt),
    });
    const dynamic = [additionalContextOf(response), ...pendingContext].filter(Boolean) as string[];
    pendingContext = [];
    pendingBytes = 0;
    if (!coreContext && dynamic.length === 0) return undefined;
    // Core is appended byte-stably every turn (prefix caching); dynamic context
    // rides only the turn it arrived on.
    const parts = [event.systemPrompt, coreContext, ...dynamic].filter(Boolean) as string[];
    return { systemPrompt: parts.join("\n\n") };
  }));

  pi.on("turn_start", GUARD_turn_start(() => { void bridge.call("ModelBefore", { session_id: sessionId }); }));
  pi.on("turn_end", GUARD_turn_end(async () => {
    await bridge.call("ModelAfter", { session_id: sessionId });
    void bridge.call("Stop", { session_id: sessionId });
  }));

  pi.on("tool_call", GUARD_tool_call(async (event: { toolName: string; input: Record<string, unknown> }) => {
    const response = await bridge.call("PreToolUse", {
      session_id: sessionId,
      tool_name: event.toolName,
      tool_input: event.input,
    });
    const context = additionalContextOf(response);
    // MAX_CONTEXT_BYTES caps ONE response, but these accumulate across every
    // tool call of a turn and drain only at the next before_agent_start — a
    // tool-heavy turn otherwise joins unbounded bytes into the system prompt.
    const bytes = context ? Buffer.byteLength(context, "utf8") : 0;
    if (context && pendingBytes + bytes <= MAX_CONTEXT_BYTES) {
      pendingContext.push(context);
      pendingBytes += bytes;
    }
  }));

  // caveman_retrieve's own output is the recovered ORIGINAL. Shrinking it hands
  // the model a fresh ccr:// mask (the proxy's classifyTool files it as an
  // ObjectCommandResult and masks anything past ~448 bytes), so recovery loops
  // instead of terminating — and registering this tool disabled the proxy's
  // server-side retrieve loop, so nothing else would strip it.
  pi.on("tool_result", GUARD_tool_result((event: Parameters<typeof shrinkToolResult>[2]) =>
    event.toolName === RECOVERY_TOOL ? undefined : shrinkToolResult(bridge, sessionId, event)));

  pi.on("session_before_compact", GUARD_session_before_compact(() => { void bridge.call("PreCompact", { session_id: sessionId }); }));

  pi.on("session_compact", GUARD_session_compact(async () => {
    const response = await bridge.call("PostCompact", { session_id: sessionId });
    const context = additionalContextOf(response);
    if (context) coreContext = context;
  }));

  pi.on("session_shutdown", GUARD_session_shutdown(async () => {
    await bridge.call("SessionEnd", { session_id: sessionId });
    router?.closeGate();
    recovery.dispose();
  }));
}

// Bridge from Pi lifecycle events to the Caveman native runtime, by invoking the
// Caveman CLI's `native-hook pi <Event>` adapter — the same single protocol
// implementation every other host uses (no second event protocol in here).

import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { homedir } from "node:os";
import { join } from "node:path";
import { type PortableInvocation, portableInvocation } from "./portable-command.ts";
import { type HookEvent, type HookResponse, sanitizeHookResponse } from "./protocol.ts";

const HOOK_TIMEOUT_MS = 2000;
// SessionStart autostarts the proxy on the CLI side (spawn + up to 2s of port
// polling on top of Node startup), so it gets a budget the CLI can actually
// meet on a cold machine.
const SESSION_START_TIMEOUT_MS = 6000;
const HOOK_MAX_BUFFER = 2 * 1024 * 1024;

export type HookInvocation = { command: string; args: string[] };

// Wrap stamps CAVEMAN_PI_HOOK_CMD as a JSON argv array; the persistent door has
// no wrap env, so fall back to the CLI on PATH.
export function resolveHookInvocations(env: NodeJS.ProcessEnv = process.env): HookInvocation[] {
  const localBin = join(env.CAVEMAN_HOME || join(homedir(), ".caveman"), "bin", "caveman");
  const candidates: HookInvocation[] = [
    { command: "caveman", args: [] },
    { command: "cave", args: [] },
    { command: localBin, args: [] },
  ];
  const stamped = env.CAVEMAN_PI_HOOK_CMD;
  if (stamped) {
    try {
      const parsed = JSON.parse(stamped);
      if (Array.isArray(parsed) && parsed.length > 0 && parsed.every((part) => typeof part === "string" && part.length > 0)) {
        // Stamped first, but never ALONE: it bakes an absolute [node, …/dist/
        // index.js] at enable time, so an nvm/node switch makes every hook call
        // ENOENT and the session degrades to permanent silent direct mode.
        candidates.unshift({ command: parsed[0], args: parsed.slice(1) });
      }
    } catch {
      // fall through to PATH resolution
    }
  }
  return candidates;
}

// TRY_NEXT tells call() that this candidate never ran the hook, so the next one
// in the list should be tried. Distinct from undefined, which means the hook ran
// and produced nothing usable (fail-open, stop).
const TRY_NEXT = "__caveman_try_next__" as const;

export class HookBridge {
  private invocations: HookInvocation[];

  constructor(invocations: HookInvocation[] = resolveHookInvocations()) {
    this.invocations = invocations;
  }

  // call runs one native-hook event. Fail-open by contract: any spawn error,
  // timeout, or unparseable output resolves to undefined.
  async call(event: HookEvent, payload: Record<string, unknown>): Promise<HookResponse | undefined> {
    const input = JSON.stringify({ event_name: event, surface: "cli", ...payload });
    for (const invocation of this.invocations) {
      const raw = await this.invoke(invocation, event, input);
      if (raw === TRY_NEXT) continue; // this candidate did not run the hook
      if (raw === undefined || !raw.trim()) return undefined;
      try {
        return sanitizeHookResponse(JSON.parse(raw));
      } catch {
        return undefined;
      }
    }
    return undefined;
  }

  private invoke(invocation: HookInvocation, event: HookEvent, input: string): Promise<string | undefined | typeof TRY_NEXT> {
    return new Promise((resolve) => {
      // On Windows `caveman` on PATH is a .cmd shim (or a non-executable Unix
      // shim beside it), and ~/.caveman/bin/caveman is extensionless — execFile
      // cannot run either and dies with `spawn EFTYPE`, which broke every hook
      // call on Windows. Resolve to something spawnable first. A shim we cannot
      // parse throws, which the fail-open contract treats as "try the next
      // candidate" rather than taking down the caller.
      let portable: PortableInvocation;
      try {
        portable = portableInvocation(invocation.command, [...invocation.args, "native-hook", "pi", event]);
      } catch {
        resolve(TRY_NEXT);
        return;
      }
      const child = execFile(
        portable.command,
        portable.args,
        { timeout: event === "SessionStart" ? SESSION_START_TIMEOUT_MS : HOOK_TIMEOUT_MS, maxBuffer: HOOK_MAX_BUFFER, encoding: "utf8" },
        (error, stdout) => {
          // Any failure that produced NO output means this candidate did not run
          // the hook, whatever the errno: a missing binary (ENOENT), a stamped
          // absolute [node, …/dist/index.js] whose script has moved (node runs
          // fine, "Cannot find module", exit 1), an unusable shim. Advancing only
          // on ENOENT stopped the loop dead on every one of those and left the
          // PATH candidates untried — the permanent silent direct mode this
          // fallback list exists to prevent.
          // A TIMEOUT is not "did not run" — the hook ran and was too slow, and
          // retrying every candidate would multiply the budget SessionStart is
          // held to. Fail open on that one, advance on the rest.
          const timedOut = !!error && (error as NodeJS.ErrnoException & { killed?: boolean }).killed === true;
          if (error && stdout === "") return resolve(timedOut ? undefined : TRY_NEXT);
          resolve(stdout);
        },
      );
      child.stdin?.on("error", () => {});
      child.stdin?.end(input);
    });
  }
}

export function promptDigest(prompt: string): { bytes: number; sha256: string } {
  return {
    bytes: Buffer.byteLength(prompt, "utf8"),
    sha256: `sha256:${createHash("sha256").update(prompt, "utf8").digest("hex")}`,
  };
}

// Task profiling: same classifier the other host plugins embed, so the runtime
// sees one vocabulary. Raw prompt text never leaves the process — only these
// bounded derived terms and the digest above.
export function taskType(text: string): string {
  const lower = text.toLowerCase();
  const has = (...terms: string[]) => terms.some((term) => lower.includes(term));
  if (has("migration", "migrate", "schema change", "backfill", "rollback")) return "migration";
  if (has("bug", "fix", "broken", "regression", "crash", "error", "incorrect")) return "bugfix";
  if (has("investigate", "diagnose", "root cause", "why does", "trace")) return "investigation";
  if (has("refactor", "restructure", "reorganize", "cleanup")) return "refactor";
  if (has("review", "audit", "critique", "assess")) return "review";
  if (has("verify", "verification", "prove", "validate", "check that")) return "verification";
  if (has("build", "implement", "add", "create", "ship", "feature")) return "feature";
  return "general";
}

const TASK_STOPWORDS = new Set(["about", "after", "agent", "before", "build", "change", "code", "create", "from", "have", "help", "implement", "into", "make", "please", "project", "repository", "should", "spec", "task", "that", "then", "there", "these", "they", "this", "through", "user", "want", "what", "when", "where", "which", "with", "would", "your"]);

export function taskTerms(text: string): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const raw of text.match(/[A-Za-z][A-Za-z0-9_./-]{2,63}/g) ?? []) {
    const term = raw.toLowerCase().replace(/^[-./]+|[-./]+$/g, "");
    if (!term || term.includes("..") || TASK_STOPWORDS.has(term) || seen.has(term)) continue;
    // Secret-looking tokens stay out of the wire entirely.
    if (/^(?:sk|pk|rk|ghp|github_pat|xox[baprs]|akia)[-_]/i.test(term) || /^[a-z0-9_-]{40,}$/i.test(term)) continue;
    seen.add(term);
    out.push(term);
    if (out.length === 12) break;
  }
  return out;
}

export function taskContinuation(text: string): boolean {
  const prompt = text.trim().toLowerCase();
  if (!prompt || prompt.length > 160 || prompt.split(/\s+/).length > 14) return false;
  return /^(?:please\s+)?(?:continue|go ahead|keep going|proceed|do (?:it|that)|fix (?:it|that)|retry|try again|explain (?:it|that)|what do you mean|yes|yep|yeah|why\??|how\??)[.!?\s]*$/.test(prompt);
}

// Windows-safe command invocation.
//
// `execFile("caveman", …)` on Windows resolves to whatever PATH offers first.
// npm/pnpm .bin directories park a NON-EXECUTABLE Unix shim under the bare name
// right next to the real `.CMD`, and `~/.caveman/bin/caveman` is likewise an
// extensionless script. Handing either to execFile fails with `spawn EFTYPE`,
// which is what took down every pi-extension hook call on Windows.
//
// Resolve through PATHEXT the way Windows does, then, for a `.cmd`/`.bat` Node
// shim, read the shim and launch its target script with the current Node binary
// directly — no shell, so no quoting surface for user-controlled paths (#834).
//
// This is a deliberate fourth copy of the helper that already lives in
// bin/lib/portable-process.js, packages/cli/src/portable-command.ts, and
// packages/agent/src/portable-process.ts. This package publishes with zero
// runtime dependencies and is esbuild-bundled, so importing across packages
// would mean taking on a dependency purely for ~50 lines. Keep the four in sync.

import { existsSync, readFileSync, statSync } from "node:fs";
import { dirname, extname, isAbsolute, join, resolve } from "node:path";

export type PortableInvocation = { command: string; args: string[] };

export function parseWindowsNodeShim(source: string): string | null {
  for (const line of source.split(/\r?\n/)) {
    if (!/(?:\bnode(?:\.exe)?\b|_prog)/i.test(line) || !/%\*/.test(line)) continue;
    // Shim-relative target (npm cmd-shim, pnpm/yarn-classic @zkochan forms), or
    // a drive-absolute target (pnpm emits one when the global bin dir and the
    // store sit on different drives — path.relative crosses drives as absolute).
    const match = line.match(/"%(?:dp0%|~dp0)\\([^"\r\n]+\.(?:cjs|mjs|js))"\s+%\*/i)
      ?? line.match(/"([A-Za-z]:[\\/][^"\r\n]+\.(?:cjs|mjs|js))"\s+%\*/i);
    if (match) return match[1]!;
  }
  return null;
}

function envValue(env: NodeJS.ProcessEnv, name: string): string | undefined {
  const key = Object.keys(env).find((candidate) => candidate.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : env[key];
}

export function resolveWindowsCommand(command: string, env: NodeJS.ProcessEnv): string | undefined {
  const pathExt = envValue(env, "PATHEXT") ?? ".COM;.EXE;.BAT;.CMD";
  // Extensionless names resolve ONLY through PATHEXT — probing the bare name
  // first picks the unusable Unix shim sitting beside the real .CMD (#834).
  const names = extname(command)
    ? [command]
    : pathExt.split(";").map((extension) =>
      `${command}${extension.startsWith(".") ? extension : `.${extension}`}`);
  // A path (~/.caveman/bin/caveman, the hook bridge's third candidate) skips
  // PATH lookup but NOT PATHEXT: returning the extensionless file straight to
  // execFile is the exact EFTYPE this file exists to prevent.
  if (isAbsolute(command) || /[\\/]/.test(command)) {
    for (const name of names) if (existsSync(name)) return name;
    return existsSync(command) ? command : undefined;
  }
  for (const directory of (envValue(env, "PATH") ?? "").split(";")) {
    if (!directory) continue;
    for (const name of names) {
      const candidate = join(directory, name);
      if (existsSync(candidate)) return candidate;
    }
  }
  return undefined;
}

// Returns the command/args pair to hand to execFile/spawn. Non-win32 is a
// pass-through, so this is safe to route every invocation through.
//
// Fail-open by contract: the hook bridge treats a throw the same as a spawn
// error, and an unresolvable command falls through to the next candidate, so a
// shim we cannot parse must never take down the caller.
export function portableInvocation(
  command: string,
  args: readonly string[],
  platform: NodeJS.Platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
): PortableInvocation {
  if (platform !== "win32") return { command, args: [...args] };
  const executable = resolveWindowsCommand(command, env) ?? command;
  if (!/\.(?:cmd|bat)$/i.test(executable)) return { command: executable, args: [...args] };
  const stat = statSync(executable);
  if (!stat.isFile() || stat.size > 256 * 1024) {
    throw new Error(`cannot safely launch Windows command shim: ${executable}`);
  }
  const shimScript = parseWindowsNodeShim(readFileSync(executable, "utf8"));
  if (!shimScript) {
    throw new Error(`cannot safely launch non-Node Windows command shim: ${executable}; install a native .exe`);
  }
  const script = /^[A-Za-z]:[\\/]/.test(shimScript)
    ? shimScript
    : resolve(dirname(executable), ...shimScript.split(/[\\/]+/));
  if (!statSync(script).isFile()) {
    throw new Error(`Windows command shim target is missing: ${script}`);
  }
  return { command: process.execPath, args: [script, ...args] };
}

// Bounded shared types for the Pi ⇄ Caveman native-runtime bridge. Mirrors the
// caps enforced by the CLI (validNativeRuntimeResponse) and the Go runtime so an
// oversized field degrades to "absent" instead of crossing the boundary.

export const MAX_CONTEXT_BYTES = 64 * 1024;
export const MAX_MESSAGE_BYTES = 4 * 1024;
export const MAX_OUTPUT_REPLACEMENT_BYTES = 2 * 1024 * 1024;
export const MAX_RECOVERY_REF_BYTES = 1024;
export const MAX_DECISION_ID_BYTES = 256;
// Hook stdin is capped at 2 MiB on the CLI side; tool output beyond this is not
// truncated (a partial payload could yield a wrong replacement) — it is skipped.
export const MAX_TOOL_OUTPUT_BYTES = 2 * 1024 * 1024;

export type HookEvent =
  | "SessionStart"
  | "UserPromptSubmit"
  | "ModelBefore"
  | "ModelAfter"
  | "Stop"
  | "PreToolUse"
  | "PostToolUse"
  | "PostToolUseFailure"
  | "PreCompact"
  | "PostCompact"
  | "SessionEnd";

export type HookResponse = {
  action?: string;
  context?: string;
  message?: string;
  output_replacement?: string;
  recovery_ref?: string;
  decision_id?: string;
  hookSpecificOutput?: {
    hookEventName?: string;
    additionalContext?: string;
    updatedToolOutput?: string;
  };
};

function fits(value: unknown, max: number): value is string {
  return typeof value === "string" && Buffer.byteLength(value, "utf8") <= max;
}

// sanitizeHookResponse drops any field that is missing, mistyped, or over its
// byte cap. Fail-open: a degenerate response becomes an empty object.
export function sanitizeHookResponse(raw: unknown): HookResponse {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const value = raw as Record<string, unknown>;
  const out: HookResponse = {};
  if (fits(value.context, MAX_CONTEXT_BYTES)) out.context = value.context;
  if (fits(value.message, MAX_MESSAGE_BYTES)) out.message = value.message;
  if (fits(value.output_replacement, MAX_OUTPUT_REPLACEMENT_BYTES)) out.output_replacement = value.output_replacement;
  if (fits(value.recovery_ref, MAX_RECOVERY_REF_BYTES)) out.recovery_ref = value.recovery_ref;
  if (fits(value.decision_id, MAX_DECISION_ID_BYTES)) out.decision_id = value.decision_id;
  if (typeof value.action === "string") out.action = value.action;
  const hso = value.hookSpecificOutput;
  if (hso && typeof hso === "object" && !Array.isArray(hso)) {
    const nested = hso as Record<string, unknown>;
    const cleaned: NonNullable<HookResponse["hookSpecificOutput"]> = {};
    if (typeof nested.hookEventName === "string") cleaned.hookEventName = nested.hookEventName;
    if (fits(nested.additionalContext, MAX_CONTEXT_BYTES)) cleaned.additionalContext = nested.additionalContext;
    if (fits(nested.updatedToolOutput, MAX_OUTPUT_REPLACEMENT_BYTES)) cleaned.updatedToolOutput = nested.updatedToolOutput;
    out.hookSpecificOutput = cleaned;
  }
  return out;
}

export function additionalContextOf(response: HookResponse | undefined): string | undefined {
  const context = response?.hookSpecificOutput?.additionalContext ?? response?.context;
  return context ? context : undefined;
}

export function outputReplacementOf(response: HookResponse | undefined): string | undefined {
  const replacement = response?.hookSpecificOutput?.updatedToolOutput ?? response?.output_replacement;
  return replacement ? replacement : undefined;
}

// Route table: which Pi model API maps to which path under the local gateway.
// APIs absent here (azure/bedrock/vertex/mistral/codex-responses/…) are
// unsupported and must never be routed (honesty: no guessed protocol).
export const ROUTES_BY_API: Readonly<Record<string, string>> = {
  "anthropic-messages": "/w/pi",
  "openai-completions": "/w/pi/openai/v1",
  "openai-responses": "/w/pi/openai/v1",
  "google-generative-ai": "/w/pi/v1beta",
};

export function routeForApi(gateway: string, api: string | undefined): string | undefined {
  const path = api ? ROUTES_BY_API[api] : undefined;
  return path ? joinUrl(gateway, path) : undefined;
}

export function joinUrl(base: string, path: string): string {
  return `${base.replace(/\/+$/, "")}${path}`;
}

// Only a loopback gateway may be routed: managed gateways need separate auth
// proof that v1 does not carry.
export function isLoopbackUrl(url: string): boolean {
  try {
    const host = new URL(url).hostname;
    return host === "127.0.0.1" || host === "::1" || host === "[::1]" || host === "localhost";
  } catch {
    return false;
  }
}

export function boundedString(value: string, max: number): string {
  if (Buffer.byteLength(value, "utf8") <= max) return value;
  return Buffer.from(value, "utf8").subarray(0, max).toString("utf8").replace(/�+$/, "");
}

// Provider routing: baseUrl-only overrides pointing the selected model's
// provider at the local Caveman gateway. No model catalogue is created and
// models.json is never replaced — Pi keeps owning auth, pricing, reasoning
// flags, context sizes, and model names.

import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { isLoopbackUrl, routeForApi } from "./protocol.ts";

type Notify = (message: string, kind: "warning" | "info") => void;

export class ProviderRouter {
  private pi: ExtensionAPI;
  private notify: Notify;
  private gateway: string | undefined;
  private gateOpen = false;
  private overridden = new Set<string>();
  private applying = false;
  private warnedModels = new Set<string>();

  constructor(pi: ExtensionAPI, notify: Notify) {
    this.pi = pi;
    this.notify = notify;
  }

  // openGate is called once per session after the recovery gate held. Refuses
  // non-loopback gateways: managed routing needs auth proof v1 does not carry.
  async openGate(gateway: string, ctx: ExtensionContext): Promise<void> {
    if (!isLoopbackUrl(gateway)) {
      this.notify("Caveman: direct mode, no compression this session (gateway is not loopback)", "warning");
      return;
    }
    this.gateway = gateway;
    this.gateOpen = true;
    await this.apply(ctx.model, ctx);
  }

  closeGate(): void {
    this.gateOpen = false;
    this.clearOverrides();
  }

  routing(): boolean {
    return this.gateOpen && this.overridden.size > 0;
  }

  // apply routes one model's provider, or restores direct mode when the model
  // has no verified route. Called from the gate and from model_select; the
  // applying flag swallows the model_select echo of our own setModel call.
  async apply(model: ExtensionContext["model"], ctx: ExtensionContext): Promise<void> {
    if (!this.gateOpen || this.applying || !this.gateway) return;
    if (!model) return;
    const route = routeForApi(this.gateway, model.api);
    let oauth = true;
    try {
      oauth = ctx.modelRegistry.isUsingOAuth(model);
    } catch {
      // Cannot determine the auth kind ⇒ treat as OAuth and refuse (uncertain ⇒ direct).
    }
    if (!route || oauth) {
      this.clearOverrides();
      const key = `${model.provider}/${model.id}`;
      if (!this.warnedModels.has(key)) {
        this.warnedModels.add(key);
        const reason = oauth ? "OAuth/subscription credentials are not routed" : `unsupported API "${model.api}"`;
        this.notify(`Caveman: pass-through for ${key} (${reason}); no compression`, "warning");
      }
      return;
    }
    this.applying = true;
    try {
      for (const provider of this.overridden) {
        if (provider !== model.provider) {
          this.pi.unregisterProvider(provider);
          this.overridden.delete(provider);
        }
      }
      this.pi.registerProvider(model.provider, { baseUrl: route });
      this.overridden.add(model.provider);
      // Re-resolve so the FIRST request uses the refreshed model object. A
      // model that cannot be re-resolved or applied would keep sending direct
      // while the registry claims routing — restore direct honestly instead.
      const refreshed = ctx.modelRegistry.find(model.provider, model.id);
      if (!refreshed || !(await this.pi.setModel(refreshed))) {
        this.clearOverrides();
        this.notify("Caveman: direct mode, no compression this session (model re-resolution failed)", "warning");
        return;
      }
    } catch {
      this.clearOverrides();
      this.notify("Caveman: direct mode, no compression this session (provider override failed)", "warning");
    } finally {
      this.applying = false;
    }
  }

  private clearOverrides(): void {
    for (const provider of this.overridden) {
      try {
        this.pi.unregisterProvider(provider);
      } catch { /* restoring direct is best-effort */ }
    }
    this.overridden.clear();
  }
}

// RecoveryClient — minimal stdio MCP client for the existing Go `caveman-mcp`
// binary. One long-lived child per session: the retrieve anti-storm ledger lives
// in that process, so a spawn-per-call client would disarm it. CCR itself is
// durable (~/.caveman/ccr.db), so a crashed child can be respawned and still
// resolve the same handles.

import { type ChildProcess, execFile, spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { delimiter, join } from "node:path";
import { type PortableInvocation, portableInvocation } from "./portable-command.ts";

const PROBE_TIMEOUT_MS = 2000;
const CALL_TIMEOUT_MS = 30_000;
// The handshake does NOT get the retrieve budget: ensure() is awaited inside
// session_start, so a caveman-mcp that starts but never answers initialize (an
// orphan holding ccr.db) froze Pi startup for the full 30s. Every other budget
// in this package is 750ms–6s; a timed-out handshake degrades the session to
// "no recovery available" instead.
const INIT_TIMEOUT_MS = 2000;

export type RetrieveResult = { text: string; isError: boolean };

export function resolveMcpBinary(env: NodeJS.ProcessEnv = process.env): string | undefined {
  const explicit = env.CAVEMAN_MCP_BIN?.trim();
  if (explicit) return explicit;
  const name = process.platform === "win32" ? "caveman-mcp.exe" : "caveman-mcp";
  for (const dir of (env.PATH ?? "").split(delimiter)) {
    if (dir && existsSync(join(dir, name))) return join(dir, name);
  }
  const local = join(env.CAVEMAN_HOME || join(homedir(), ".caveman"), "bin", name);
  return existsSync(local) ? local : undefined;
}

type Pending = { resolve: (value: unknown) => void; reject: (error: Error) => void; timer: NodeJS.Timeout };

export class RecoveryClient {
  private binary: string | undefined;
  private child: ChildProcess | undefined;
  private initialized = false;
  private probed: boolean | undefined;
  private ensuring: Promise<boolean> | undefined;
  private nextId = 1;
  private pending = new Map<number, Pending>();
  private buffer = "";
  private disposed = false;

  constructor(binary: string | undefined = resolveMcpBinary()) {
    this.binary = binary;
  }

  // ensure probes the binary once and brings up an initialized child. Returns
  // false (never throws) when recovery cannot hold — the caller passes through.
  async ensure(): Promise<boolean> {
    if (this.disposed || !this.binary) return false;
    if (this.child && this.initialized) return true;
    // probed/child are assigned only after an await, so N concurrent callers
    // used to run N probes and N spawns with only the LAST child tracked — the
    // rest stayed alive as orphans holding ccr.db. One in-flight bring-up,
    // shared by everyone who asks while it runs.
    this.ensuring ??= this.bringUp().finally(() => { this.ensuring = undefined; });
    return this.ensuring;
  }

  private async bringUp(): Promise<boolean> {
    if (this.probed === undefined) this.probed = await this.probe();
    if (!this.probed || this.disposed) return false;
    if (this.child && this.initialized) return true;
    return this.start();
  }

  ready(): boolean {
    return Boolean(this.child && this.initialized && !this.disposed);
  }

  async retrieve(handle: string, query: string | undefined, signal: AbortSignal | undefined): Promise<RetrieveResult> {
    if (!(await this.ensure())) {
      return { text: JSON.stringify({ error: "cave_recovery_unavailable", message: "caveman-mcp is not available this session" }), isError: true };
    }
    try {
      const result = await this.call("tools/call", {
        name: "caveman_retrieve",
        arguments: { recovery_handle: handle, ...(query ? { query } : {}) },
      }, signal);
      const value = result as { content?: Array<{ type?: string; text?: string }>; isError?: boolean };
      const text = (value.content ?? []).map((block) => (block.type === "text" && typeof block.text === "string" ? block.text : "")).join("");
      return { text, isError: Boolean(value.isError) };
    } catch (error) {
      // Transport failure ≠ content: surface the mechanism, never fabricate bytes.
      return { text: JSON.stringify({ error: "cave_recovery_transport", message: (error as Error).message }), isError: true };
    }
  }

  dispose(): void {
    this.disposed = true;
    const child = this.child;
    this.child = undefined;
    this.initialized = false;
    for (const [, entry] of this.pending) {
      clearTimeout(entry.timer);
      entry.reject(new Error("recovery client disposed"));
    }
    this.pending.clear();
    this.stop(child);
    // A bring-up still in flight spawns after this returns; start() sees the
    // disposed flag and reaps its own child, but await it here too so a caller
    // that disposes mid-ensure() cannot leave one behind.
    void this.ensuring?.then(() => { const late = this.child; this.child = undefined; this.stop(late); });
  }

  // resolveMcpBinary appends .exe on win32, but CAVEMAN_MCP_BIN is an operator
  // override that can name anything — including a .cmd shim, which execFile
  // and spawn both refuse with EFTYPE. Route through the same resolver the hook
  // bridge uses so the override is as spawnable as the default. Fail-closed:
  // callers treat a throw as "recovery cannot hold" and pass through.
  private invocation(args: string[]): PortableInvocation | undefined {
    try {
      return portableInvocation(this.binary!, args);
    } catch {
      return undefined;
    }
  }

  private probe(): Promise<boolean> {
    return new Promise((resolve) => {
      const portable = this.invocation(["version", "--json"]);
      if (!portable) return resolve(false);
      execFile(portable.command, portable.args, { timeout: PROBE_TIMEOUT_MS, encoding: "utf8" }, (error, stdout) => {
        if (error) return resolve(false);
        try {
          const parsed = JSON.parse(stdout);
          resolve(Array.isArray(parsed?.capabilities) && parsed.capabilities.includes("mcp_recovery"));
        } catch {
          resolve(false);
        }
      });
    });
  }

  private async start(): Promise<boolean> {
    let child: ChildProcess;
    try {
      const portable = this.invocation([]);
      if (!portable) return false;
      child = spawn(portable.command, portable.args, { stdio: ["pipe", "pipe", "ignore"] });
    } catch {
      return false;
    }
    this.child = child;
    this.initialized = false;
    this.buffer = "";
    child.on("error", () => this.onChildGone(child));
    child.on("exit", () => this.onChildGone(child));
    // stdin needs its own listener. Node emits 'error' ON THE STREAM in addition
    // to invoking the write callback, so when caveman-mcp dies mid-call the EPIPE
    // became an unhandled 'error' and killed the Pi host — the one thing
    // guardedBase promises never happens. The write callback in call() rejects
    // that request; this reaps the child so the next call degrades to "recovery
    // unavailable" instead of throwing. lifecycle.ts does the same for its hooks.
    child.stdin?.on("error", () => this.onChildGone(child));
    child.stdout?.setEncoding("utf8");
    child.stdout?.on("data", (chunk: string) => this.onData(chunk));
    try {
      await this.call("initialize", {
        protocolVersion: "2024-11-05",
        capabilities: {},
        clientInfo: { name: "caveman-pi-extension", version: "0.1.0" },
      }, undefined, INIT_TIMEOUT_MS);
      this.notify("notifications/initialized");
      if (this.disposed) { this.onChildGone(child); this.stop(child); return false; }
      this.initialized = true;
      return true;
    } catch {
      // A child that failed (or never finished) the handshake is unusable and
      // still holds ccr.db — reap it rather than leaving it for the next spawn
      // to collide with.
      this.onChildGone(child);
      this.stop(child);
      return false;
    }
  }

  private stop(child: ChildProcess | undefined): void {
    if (!child) return;
    try { child.stdin?.end(); } catch { /* already gone */ }
    // Deliberately NOT unref'd. On session_shutdown "quit" the event loop drains
    // straight away, so an unref'd timer never fires and a child that ignored the
    // stdin close was never signalled at all — it outlived the host still holding
    // ccr.db. Both timers are cleared the moment the child exits, so a
    // well-behaved child still costs nothing.
    const term = setTimeout(() => { try { child.kill("SIGTERM"); } catch { /* already gone */ } }, 500);
    const kill = setTimeout(() => { try { child.kill("SIGKILL"); } catch { /* already gone */ } }, 2000);
    child.once("exit", () => { clearTimeout(term); clearTimeout(kill); });
  }

  private onChildGone(child: ChildProcess): void {
    if (this.child !== child) return;
    this.child = undefined;
    this.initialized = false;
    for (const [, entry] of this.pending) {
      clearTimeout(entry.timer);
      entry.reject(new Error("caveman-mcp exited"));
    }
    this.pending.clear();
  }

  private onData(chunk: string): void {
    this.buffer += chunk;
    let newline: number;
    while ((newline = this.buffer.indexOf("\n")) !== -1) {
      const line = this.buffer.slice(0, newline).trim();
      this.buffer = this.buffer.slice(newline + 1);
      if (!line) continue;
      let message: { id?: unknown; result?: unknown; error?: { message?: string } };
      try {
        message = JSON.parse(line);
      } catch {
        continue;
      }
      if (typeof message.id !== "number") continue;
      const entry = this.pending.get(message.id);
      if (!entry) continue;
      this.pending.delete(message.id);
      clearTimeout(entry.timer);
      if (message.error) entry.reject(new Error(message.error.message || "caveman-mcp error"));
      else entry.resolve(message.result);
    }
  }

  private call(method: string, params: Record<string, unknown>, signal: AbortSignal | undefined, timeoutMs = CALL_TIMEOUT_MS): Promise<unknown> {
    const child = this.child;
    if (!child?.stdin?.writable) return Promise.reject(new Error("caveman-mcp not running"));
    if (signal?.aborted) return Promise.reject(new Error("retrieve cancelled"));
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(new Error(`caveman-mcp ${method} timed out`));
      }, timeoutMs);
      timer.unref?.();
      const onAbort = () => {
        this.pending.delete(id);
        clearTimeout(timer);
        reject(new Error("retrieve cancelled"));
      };
      signal?.addEventListener("abort", onAbort, { once: true });
      this.pending.set(id, {
        resolve: (value) => { signal?.removeEventListener("abort", onAbort); resolve(value); },
        reject: (error) => { signal?.removeEventListener("abort", onAbort); reject(error); },
        timer,
      });
      child.stdin!.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n", (error) => {
        if (error) {
          this.pending.delete(id);
          clearTimeout(timer);
          signal?.removeEventListener("abort", onAbort);
          reject(error);
        }
      });
    });
  }

  private notify(method: string): void {
    try {
      this.child?.stdin?.write(JSON.stringify({ jsonrpc: "2.0", method }) + "\n");
    } catch { /* fail-open */ }
  }
}

// Test-only surface: re-exports internals so the node --test suite can exercise
// them from the built dist without reaching into TS sources.
export * from "./protocol.ts";
export { HookBridge, promptDigest, resolveHookInvocations, taskContinuation, taskTerms, taskType } from "./lifecycle.ts";
export { RecoveryClient, resolveMcpBinary } from "./recovery.ts";

// Post-tool output shrinking via the native runtime's PostToolUse decision.
// The runtime decides; this side only applies a valid replacement and carries
// the recovery handle embedded in it. Anything abnormal keeps the original.

import type { ToolResultEvent } from "@earendil-works/pi-coding-agent";
import type { HookBridge } from "./lifecycle.ts";
import { MAX_TOOL_OUTPUT_BYTES, outputReplacementOf } from "./protocol.ts";

// Partial-patch result shape for tool_result handlers (ToolResultEventResult is
// not re-exported from the package root; omitted fields keep current values).
type ToolResultPatch = { content: ToolResultEvent["content"] };

export async function shrinkToolResult(
  bridge: HookBridge,
  sessionId: string,
  event: ToolResultEvent,
): Promise<ToolResultPatch | undefined> {
  const text = event.content
    .map((block) => (block.type === "text" && typeof block.text === "string" ? block.text : ""))
    .join("");
  if (!text) return undefined;
  // Over-cap output is skipped, not truncated: a partial payload could produce
  // a replacement whose recovery handle does not cover the elided bytes.
  if (Buffer.byteLength(text, "utf8") > MAX_TOOL_OUTPUT_BYTES) return undefined;
  const response = await bridge.call(event.isError ? "PostToolUseFailure" : "PostToolUse", {
    session_id: sessionId,
    tool_name: event.toolName,
    tool_input: event.input,
    tool_output: text,
  });
  const replacement = outputReplacementOf(response);
  if (!replacement) return undefined;
  // Replace only the model-facing text; non-text blocks (images) were never
  // sent to the runtime, are not covered by the recovery handle, and must
  // survive the replacement byte-for-byte. Details keep the renderer's shape.
  return { content: [{ type: "text", text: replacement }, ...event.content.filter((block) => block.type !== "text")] };
}

#!/usr/bin/env node
// Stub caveman-mcp: `version --json` probe + line-delimited MCP JSON-RPC with a
// single known handle. STUB_MCP_DROP_CAPABILITY=1 removes mcp_recovery from the
// probe; STUB_MCP_EXIT_AFTER_INIT=1 dies right after initialize (crash test);
// STUB_MCP_EXIT_ONCE_FLAG=<path> dies after initialize only on the FIRST spawn,
// creating that file as the marker. The once-flag lives here rather than in a
// shell shim because the launcher is bypassed on Windows: portableInvocation
// extracts the node target from a .cmd and runs it directly, so anything the
// shim tried to set never executed.
// STUB_MCP_HANG_INIT=1 starts but never answers initialize — the locked-ccr.db
// case that used to hold Pi's session_start for the full 30s call budget.
// STUB_MCP_SPAWN_LOG=<path> appends one pid line per serve-mode spawn, so a
// test can count how many children ensure() actually created and whether
// dispose() reaped them.

import { appendFileSync, existsSync, writeFileSync } from "node:fs";

const KNOWN_HANDLE = "ccr_0123456789abcdef0123456789abcdef";
const KNOWN_BYTES = "exact original bytes\nline two éø bytes";

if (process.argv[2] === "version") {
  const capabilities = process.env.STUB_MCP_DROP_CAPABILITY === "1" ? ["build_stamped_version"] : ["mcp_recovery", "build_stamped_version"];
  process.stdout.write(JSON.stringify({ version: "1.0.0", schema: "caveman.mcp.version.v1", capabilities }) + "\n");
  process.exit(0);
}

const spawnLog = process.env.STUB_MCP_SPAWN_LOG;
if (spawnLog) appendFileSync(spawnLog, `${process.pid}\n`);

let buffer = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  buffer += chunk;
  let index;
  while ((index = buffer.indexOf("\n")) !== -1) {
    const line = buffer.slice(0, index).trim();
    buffer = buffer.slice(index + 1);
    if (!line) continue;
    let message;
    try { message = JSON.parse(line); } catch { continue; }
    if (message.method === "initialize") {
      if (process.env.STUB_MCP_HANG_INIT === "1") continue; // alive, silent — never answers
      reply(message.id, { protocolVersion: "2024-11-05", capabilities: { tools: {} }, serverInfo: { name: "stub", version: "1.0.0" } });
      if (process.env.STUB_MCP_EXIT_AFTER_INIT === "1") process.exit(1);
      const onceFlag = process.env.STUB_MCP_EXIT_ONCE_FLAG;
      if (onceFlag && !existsSync(onceFlag)) {
        writeFileSync(onceFlag, "");
        process.exit(1);
      }
    } else if (message.method === "tools/call") {
      const args = message.params?.arguments ?? {};
      if (message.params?.name !== "caveman_retrieve") {
        reply(message.id, { content: [{ type: "text", text: JSON.stringify({ error: "cave_unknown_tool" }) }], isError: true });
      } else if (args.recovery_handle === KNOWN_HANDLE) {
        reply(message.id, { content: [{ type: "text", text: KNOWN_BYTES }], isError: false });
      } else {
        reply(message.id, { content: [{ type: "text", text: JSON.stringify({ error: "cave_unknown_handle", message: "no original found for handle" }) }], isError: true });
      }
    } else if (message.id !== undefined) {
      reply(message.id, {});
    }
  }
});

function reply(id, result) {
  process.stdout.write(JSON.stringify({ jsonrpc: "2.0", id, result }) + "\n");
}

// Registers a loopback test provider so integration runs never leave the
// machine: direct (ungated) traffic fast-fails on a dead local port, and gated
// traffic goes wherever the caveman extension routes it.
export default function (pi) {
  pi.registerProvider("stubprov", {
    name: "Stub Provider",
    baseUrl: "http://127.0.0.1:1",
    apiKey: "dummy-key-for-stub",
    api: "openai-completions",
    models: [{
