    // above), and returning it verbatim is the EFTYPE this file exists to stop.
    writeFileSync(join(bin, "caveman"), "#!/bin/sh\nexec node caveman.js\n");
    writeFileSync(join(bin, "caveman.CMD"), '@node  "%~dp0\\cli.js" %*\r\n');
